#!/bin/bash
# Tests for the CI-signed passwordless-deploy path: the verifier/deployer (eve-deploy), the packer (make-release.sh), the installer,
# the uninstaller and the fetch helper. Runs unprivileged: eve-deploy is SOURCED (it only runs main when executed) and its fixed
# paths are pointed at a temp dir. The signature tests use REAL Sigstore bundles produced by the CI signing workflow
# (test/fixtures/, regenerated by .github/workflows/test-fixtures.yml) and the real pinned cosign + trust root, verified OFFLINE.
#   bash deploy/nopasswd/test/run.sh          (EVE_TEST_COSIGN=/path/to/cosign skips the pinned download)
# Needs: bash, cosign (downloaded + sha256-pinned below if not given), tar, git, visudo, install, sha256sum or shasum. Linux and macOS (bash 3.2).
# shellcheck disable=all
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
D=$(cd "$HERE/.." && pwd)
REPO_ROOT=$(cd "$D/../.." && pwd)
ENTRY=$D/eve-deploy
FX=$HERE/fixtures
umask 022
T=$(cd "$(mktemp -d)" && pwd -P); trap 'rm -rf "$T"' EXIT
PASS=0; FAILN=0
ok()   { PASS=$((PASS + 1)); }
bad()  { FAILN=$((FAILN + 1)); echo "FAIL: $*"; }
eq()   { if [ "$2" = "$3" ]; then ok; else bad "$1: got [$2] want [$3]"; fi; }
yes_() { local n=$1; shift; if "$@" >/dev/null 2>&1; then ok; else bad "$n: expected success: $*"; fi; }
no_()  { local n=$1; shift; if "$@" >/dev/null 2>&1; then bad "$n: expected failure: $*"; else ok; fi; }

sha256() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }
modeof() { stat -c %a "$1" 2>/dev/null || stat -f %Lp "$1"; }
# shellcheck source=../eve-deploy
. "$ENTRY"

# ---------------- the pinned cosign (this is also how CI gets it) ----------------
COSIGN_BIN=${EVE_TEST_COSIGN:-}
if [ -z "$COSIGN_BIN" ]; then
  case "$(uname -s)/$(uname -m)" in
    Linux/x86_64) cn=cosign-linux-amd64; ch=424e2c97d0b45fd7a6b608a87f090f35633f4c23ece5f092d48bba11aaf4bbfa;;
    Linux/aarch64|Linux/arm64) cn=cosign-linux-arm64; ch=ade83b7aac62e131cacfe96d958948b2150cc9efec46a570a2649b8e27dedad2;;
    Darwin/arm64) cn=cosign-darwin-arm64; ch=9f9b8cd557cf2e5b3df3373a00baa005a86b02391e3e06dd0ce37b3a1533d3a4;;
    Darwin/x86_64) cn=cosign-darwin-amd64; ch=9d1e4abe2b6be279ed0d2ff706fde1ccd738747c834e3e6d44039c238867334f;;
    *) cn=""; ch="";;
  esac
  if [ -n "$cn" ] && curl -fsSL --proto '=https' --tlsv1.2 --retry 3 -o "$T/cosign.dl" "https://github.com/sigstore/cosign/releases/download/v3.1.4/$cn" 2>/dev/null \
     && [ "$(sha256 "$T/cosign.dl")" = "$ch" ]; then COSIGN_BIN=$T/cosign.dl; fi
fi
[ -n "$COSIGN_BIN" ] && [ -x "$COSIGN_BIN" ] || chmod 0755 "$COSIGN_BIN" 2>/dev/null
[ -n "$COSIGN_BIN" ] && [ -x "$COSIGN_BIN" ] || { echo "FAIL: no cosign available (set EVE_TEST_COSIGN, or allow the pinned download)"; exit 1; }
cp "$COSIGN_BIN" "$T/cosign"; chmod 0755 "$T/cosign"; COSIGN_T=$T/cosign; COSIGN_T_SHA=$(sha256 "$COSIGN_T")
cp "$D/trusted_root.json" "$T/trusted_root.json"; chmod 0644 "$T/trusted_root.json"

# ---------------- version validation / comparison / argument parsing ----------------
for v in 5.0.0 0.0.0 0.0.1 1.2.3 10.20.30 999999999.999999999.999999999; do yes_ "valid $v" valid_version "$v"; done
for v in "" 1 1.2 1.2.3.4 01.2.3 1.02.3 1.2.03 v1.2.3 1.2.3-rc1 1.2.3+b1 "1.2.3 " " 1.2.3" $'1.2.3\n' $'\n1.2.3' 1.2.x -1.2.3 1..3 .1.2 1.2. \
         "1.2.3;id" '$(id).0.0' 1000000000.0.0 1.2.3/../x '1.2.3 5.0.0' 1e3.0.0 0x1.0.0; do no_ "invalid [$v]" valid_version "$v"; done
cmp() { ver_cmp "$1" "$2"; }
eq "5.0.1 > 5.0.0" "$(cmp 5.0.1 5.0.0)" 1
eq "5.0.0 = 5.0.0" "$(cmp 5.0.0 5.0.0)" 0
eq "4.9.9 < 5.0.0" "$(cmp 4.9.9 5.0.0)" -1
eq "5.10.0 > 5.9.0" "$(cmp 5.10.0 5.9.0)" 1
eq "5.9.0 < 5.10.0" "$(cmp 5.9.0 5.10.0)" -1
eq "10.0.0 > 9.0.0" "$(cmp 10.0.0 9.0.0)" 1
eq "5.0.10 > 5.0.9" "$(cmp 5.0.10 5.0.9)" 1
eq "6.0.0 > 5.99.99" "$(cmp 6.0.0 5.99.99)" 1
eq "999999999.0.0 > 999999998.9.9" "$(cmp 999999999.0.0 999999998.9.9)" 1
for pair in "5.0.0 bad" "bad 5.0.0" "5.0 5.0.0" "5.0.0 05.0.0" "5.0.0 ''"; do
  set -- $pair; ver_cmp "$1" "$2" >/dev/null 2>&1; eq "cmp malformed [$pair]" "$?" 2
done
yes_ "args deploy" parse_args deploy 5.0.1;      eq "deploy" "$ACTION $KIND $TARGET" "deploy gateway 5.0.1"
yes_ "args deploy-web" parse_args deploy-web 1.2.3; eq "deploy-web" "$ACTION $KIND $TARGET" "deploy web 1.2.3"
yes_ "args rollback" parse_args rollback;        eq "rollback" "$ACTION $KIND:$TARGET" "rollback gateway:"
yes_ "args rollback-web" parse_args rollback-web; eq "rollback-web" "$ACTION $KIND:$TARGET" "rollback web:"
for a in "" "deploy" "rollback now" "rollback-web 1.0.0" "deploy-web" "deploy 5.0" "deploy 5.0.1 extra" "Deploy 5.0.1" "ROLLBACK" "install 5.0.1" "--help" "-h" "-- 5.0.1" \
         "deploy --" "sh -c id" "5.0.1 deploy" "deploy rollback" "deploy-web 05.0.1" "deploy-web bad" "fetch 1.0.0" "deploy ."; do
  set -- $a; no_ "args [$a]" parse_args "$@"
done
no_ "args single quoted string" parse_args "deploy 5.0.1"
no_ "args newline version" parse_args deploy $'5.0.1\n'
no_ "args empty" parse_args ""
for args in "" "deploy" "rollback x" "deploy 5.0" "deploy 5.0.1 x" "foo" "-h" "deploy 05.0.1" "deploy-web" "rollback-web x"; do
  bash "$ENTRY" $args >/dev/null 2>&1; eq "exec rejects [$args]" "$?" 2
done
bash "$ENTRY" deploy '' >/dev/null 2>&1; eq "exec rejects empty version" "$?" 2
if [ "$(id -u)" != 0 ]; then bash "$ENTRY" deploy 5.0.1 >/dev/null 2>&1; eq "exec non-root refused" "$?" 1; fi

# ---------------- the real CI-signed fixtures ----------------
for f in eve-gateway-9.1.0 eve-web-9.1.0; do for e in MANIFEST sigstore.json tar; do [ -s "$FX/$f.$e" ] && ok || bad "missing fixture $f.$e"; done; done
FXV=9.1.0
FX_REF=$(sed -n 's/^ref=//p' "$FX/eve-gateway-$FXV.MANIFEST"); FX_SHA=$(sed -n 's/^git_sha=//p' "$FX/eve-gateway-$FXV.MANIFEST")
FX_REPO=$(sed -n 's/^repo=//p' "$FX/eve-gateway-$FXV.MANIFEST")
FX_ID="https://github.com/$FX_REPO/.github/workflows/deploy-sign.yml@$FX_REF"
eq "fixture was signed from the throwaway fixture ref (not a tag, not main)" "${FX_REF%%/ci-signed*}" "refs/heads/fixture"
ME=$(id -un); MYUID=$(id -u)

new_box() { # fresh sandbox: live 9.0.0 binaries and UI, state, staging
  B=$T/box.$1; rm -rf "$B"; mkdir -p "$B/bin" "$B/state" "$B/staging" "$B/web" "$B/out"
  echo "gw-old" >"$B/bin/gateway"; echo "eg-old" >"$B/bin/eve-gw"; chmod 0755 "$B/bin/"*
  echo "old" >"$B/web/index.html"; echo "oldjs" >"$B/web/sw.js"
  echo 9.0.0 >"$B/state/current_version"; echo 8 >"$B/state/schema"; echo 9.0.0 >"$B/state/current_web_version"; echo "$ME" >"$B/state/allowed_user"
}
# the sandbox: every fixed path points into $B, the trust pins point at the fixture's CI identity (the production pins are tested separately)
sandbox_env() {
  STATE=$B/state; BIN_DIR=$B/bin; WEB_DIR=$B/web; STAGING=$B/staging; LOGF=$B/log
  OWNER_ARGS=""; CHOWN_SPEC=""; ROOT_UID=$MYUID; SUDO_USER=$ME; SUDO_UID=$MYUID; GW_UID=$((MYUID + 100000))
  COSIGN=$COSIGN_T; COSIGN_SHA256S="$COSIGN_T_SHA"; TRUSTED_ROOT=$T/trusted_root.json
  SIGNER_IDENTITY=$FX_ID; REPO_GATEWAY=$FX_REPO; REPO_WEB=$FX_REPO; REF_FMT=$FX_REF; HOST_ARCH_WANT=$(uname -m)
  require_root() { :; }
  svc_restart() { echo restart >>"$B/svc"; }
  health_ok() { [ "$(cat "$B/health" 2>/dev/null || echo ok)" = ok ]; }
  ui_ok() { [ "$(cat "$B/uihealth" 2>/dev/null || echo ok)" = ok ]; }
}
stage() { # $1 kind (gateway|web)  [$2 name to stage under: default = same]  [$3 dir with the files: default fixtures]
  local k=$1 as=${2:-$1} src=${3:-$FX} e
  for e in MANIFEST sigstore.json tar; do cp "$src/eve-$k-$FXV.$e" "$B/staging/eve-$as-$FXV.$e"; done
}
run_main() { ( sandbox_env; main "$@" ) >"$B/stdout" 2>"$B/stderr"; }
live() { echo "$(cat "$B/bin/gateway" | head -2 | tr '\n' ' ')/$(cat "$B/state/current_version")"; }
fx_gw_content=$(tar -xOf "$FX/eve-gateway-$FXV.tar" gateway)
livegw_is_fixture() { [ "$(cat "$B/bin/gateway")" = "$fx_gw_content" ]; }
logs() { cat "$B/log" 2>/dev/null; }

# 1. happy path with a REAL CI signature, verified offline against the pinned trust root
new_box 1; stage gateway
run_main deploy $FXV; eq "deploy ok rc" "$?" 0
livegw_is_fixture && ok || bad "deploy ok: live gateway is the signed one"
eq "deploy ok: version recorded" "$(cat "$B/state/current_version")" $FXV
eq "previous version kept" "$(cat "$B/state/previous/version")" 9.0.0
eq "previous binary kept" "$(cat "$B/state/previous/gateway")" gw-old
eq "eve-gw installed from the bundle" "$(cat "$B/bin/eve-gw")" "$(tar -xOf "$FX/eve-gateway-$FXV.tar" eve-gw)"
eq "service restarted once" "$(wc -l <"$B/svc" | tr -d ' ')" 1
[ ! -d "$B/state/lock" ] && ok || bad "lock released"
eq "no work dir left" "$(ls "$B/state" | grep -c '^work\.')" 0
logs | grep -q "signature OK for gateway $FXV (commit $FX_SHA" && ok || bad "log records the signing commit"
run_main rollback; eq "rollback rc" "$?" 0
eq "rollback live" "$(cat "$B/bin/gateway")/$(cat "$B/state/current_version")" "gw-old/9.0.0"
run_main rollback; eq "second rollback refused" "$?" 1
run_main deploy 9.0.0; eq "after rollback the same/lower version is refused" "$?" 1

# 2. DOWNGRADE / replay: a validly signed older (or equal) release is refused when something newer is installed
new_box 2; stage gateway; echo 9.2.0 >"$B/state/current_version"
run_main deploy $FXV; eq "signed 9.1.0 over installed 9.2.0 (downgrade) refused" "$?" 1
grep -q "not higher" "$B/stderr" && ok || bad "downgrade refusal says why"
echo $FXV >"$B/state/current_version"; run_main deploy $FXV; eq "same version refused" "$?" 1
echo 9.10.0 >"$B/state/current_version"; run_main deploy $FXV; eq "9.1.0 < installed 9.10.0 (numeric, not lexical) refused" "$?" 1
echo 9.0.9 >"$B/state/current_version"; run_main deploy $FXV; eq "9.1.0 > installed 9.0.9 accepted" "$?" 0
new_box 2b; stage web; echo 9.2.0 >"$B/state/current_web_version"
run_main deploy-web $FXV; eq "web downgrade refused" "$?" 1
eq "downgrade: live gateway/web untouched" "$(cat "$B/bin/gateway")/$(cat "$B/web/index.html")" "gw-old/old"
# the entrypoint refuses to deploy if the version asked for is not the one that was signed: stage 9.1.0 under another version's name
new_box 3; for e in MANIFEST sigstore.json tar; do cp "$FX/eve-gateway-$FXV.$e" "$B/staging/eve-gateway-9.5.0.$e"; done
run_main deploy 9.5.0; eq "signed 9.1.0 staged as 9.5.0 (version relabel) refused" "$?" 1
grep -q "manifest version" "$B/stderr" && ok || bad "relabel refused by the manifest check"

# 3. BAD SIGNATURE: any change to the signed manifest, a damaged/foreign bundle, a missing bundle
new_box 4; stage gateway; sed 's/^built_at=.*/built_at=2020-01-01T00:00:00Z/' "$FX/eve-gateway-$FXV.MANIFEST" >"$B/staging/eve-gateway-$FXV.MANIFEST"
run_main deploy $FXV; eq "edited manifest (valid shape, wrong signature) refused" "$?" 1
grep -q "signature verification FAILED" "$B/stderr" && ok || bad "edited manifest fails on the signature"
new_box 5; stage gateway; head -c 6000 "$FX/eve-gateway-$FXV.sigstore.json" >"$B/staging/eve-gateway-$FXV.sigstore.json"
run_main deploy $FXV; eq "truncated sigstore bundle refused" "$?" 1
new_box 6; stage gateway; cp "$FX/eve-web-$FXV.sigstore.json" "$B/staging/eve-gateway-$FXV.sigstore.json"
run_main deploy $FXV; eq "another artifact's valid bundle refused" "$?" 1
new_box 7; stage gateway; rm "$B/staging/eve-gateway-$FXV.sigstore.json"; run_main deploy $FXV; eq "missing bundle refused" "$?" 1
new_box 8; stage gateway; printf '{}' >"$B/staging/eve-gateway-$FXV.sigstore.json"; run_main deploy $FXV; eq "empty-json bundle refused" "$?" 1
# an attacker who also rewrites the manifest to match an evil tar still has no signature for it
new_box 9; stage gateway; mkdir "$B/t" && ( cd "$B/t" && echo evil >gateway && tar -cf "$B/staging/eve-gateway-$FXV.tar" gateway )
sed "s/^sha256.bundle=.*/sha256.bundle=$(sha256 "$B/staging/eve-gateway-$FXV.tar")/;s/^sha256.gateway=.*/sha256.gateway=$(sha256 "$B/t/gateway")/;/^sha256.eve-gw=/d" "$FX/eve-gateway-$FXV.MANIFEST" >"$B/staging/eve-gateway-$FXV.MANIFEST"
run_main deploy $FXV; eq "evil tar + rewritten manifest refused (no signature for it)" "$?" 1
grep -q "signature verification FAILED" "$B/stderr" && ok || bad "rewritten manifest fails on the signature"
eq "bad signatures: live untouched" "$(cat "$B/bin/gateway")/$(cat "$B/state/current_version")" "gw-old/9.0.0"
# same through verify_sig directly: wrong pins, one at a time (identity / issuer / repo / ref / commit / trigger)
vs() { ( sandbox_env; WORK=$T/vs; mkdir -p "$WORK"; "$@" ) >/dev/null 2>&1; }
vs_run() { ( sandbox_env; B=$T/vsbox; mkdir -p "$B"; LOGF=$B/log; WORK=$T/vsw; rm -rf "$WORK"; mkdir -p "$WORK"; "$@"; ) >/dev/null 2>&1; }
M=$FX/eve-gateway-$FXV.MANIFEST; SB=$FX/eve-gateway-$FXV.sigstore.json
yes_ "verify_sig: right pins accepted" vs_run verify_sig "$M" "$SB" "$FX_REPO" "$FX_REF" "$FX_SHA"
no_ "verify_sig: production ref (refs/tags/v9.1.0) != the fixture's branch ref  [wrong ref]" vs_run verify_sig "$M" "$SB" "$FX_REPO" refs/tags/v9.1.0 "$FX_SHA"
no_ "verify_sig: main as ref" vs_run verify_sig "$M" "$SB" "$FX_REPO" refs/heads/main "$FX_SHA"
no_ "verify_sig: wrong repo (a fork)" vs_run verify_sig "$M" "$SB" attacker/eve-serving "$FX_REF" "$FX_SHA"
no_ "verify_sig: wrong commit sha" vs_run verify_sig "$M" "$SB" "$FX_REPO" "$FX_REF" 0000000000000000000000000000000000000000
no_ "verify_sig: production signer identity (deploy-sign.yml@main) != fixture's" vs_run bash -c ". '$ENTRY'; SIGNER_IDENTITY=https://github.com/gun025bba/eve-serving/.github/workflows/deploy-sign.yml@refs/heads/main; COSIGN=$COSIGN_T; COSIGN_SHA256S=$COSIGN_T_SHA; TRUSTED_ROOT=$T/trusted_root.json; ROOT_UID=$MYUID; LOGF=$T/vsbox/log; WORK=$T/vsw; mkdir -p \$WORK; verify_sig '$M' '$SB' '$FX_REPO' '$FX_REF' '$FX_SHA'"
no_ "verify_sig: another workflow file as signer" vs_run bash -c ". '$ENTRY'; SIGNER_IDENTITY='${FX_ID/deploy-sign.yml/ci.yml}'; COSIGN=$COSIGN_T; COSIGN_SHA256S=$COSIGN_T_SHA; TRUSTED_ROOT=$T/trusted_root.json; ROOT_UID=$MYUID; LOGF=$T/vsbox/log; WORK=$T/vsw; mkdir -p \$WORK; verify_sig '$M' '$SB' '$FX_REPO' '$FX_REF' '$FX_SHA'"
no_ "verify_sig: wrong OIDC issuer" vs_run bash -c ". '$ENTRY'; OIDC_ISSUER=https://evil.example; SIGNER_IDENTITY='$FX_ID'; COSIGN=$COSIGN_T; COSIGN_SHA256S=$COSIGN_T_SHA; TRUSTED_ROOT=$T/trusted_root.json; ROOT_UID=$MYUID; LOGF=$T/vsbox/log; WORK=$T/vsw; mkdir -p \$WORK; verify_sig '$M' '$SB' '$FX_REPO' '$FX_REF' '$FX_SHA'"
no_ "verify_sig: wrong trigger pin (pull_request)" vs_run bash -c ". '$ENTRY'; SIGNER_TRIGGER=pull_request; SIGNER_IDENTITY='$FX_ID'; COSIGN=$COSIGN_T; COSIGN_SHA256S=$COSIGN_T_SHA; TRUSTED_ROOT=$T/trusted_root.json; ROOT_UID=$MYUID; LOGF=$T/vsbox/log; WORK=$T/vsw; mkdir -p \$WORK; verify_sig '$M' '$SB' '$FX_REPO' '$FX_REF' '$FX_SHA'"
# a trust root that does not contain the signing CA/log refuses the same bundle
printf '{"mediaType":"application/vnd.dev.sigstore.trustedroot+json;version=0.1","tlogs":[],"certificateAuthorities":[],"ctlogs":[],"timestampAuthorities":[]}' >"$T/empty_root.json"
no_ "verify_sig: empty trust root refuses" vs_run bash -c ". '$ENTRY'; SIGNER_IDENTITY='$FX_ID'; COSIGN=$COSIGN_T; COSIGN_SHA256S=$COSIGN_T_SHA; TRUSTED_ROOT=$T/empty_root.json; TRUSTED_ROOT_SHA256=$(sha256 "$T/empty_root.json"); ROOT_UID=$MYUID; LOGF=$T/vsbox/log; WORK=$T/vsw; mkdir -p \$WORK; verify_sig '$M' '$SB' '$FX_REPO' '$FX_REF' '$FX_SHA'"

# 4. WRONG REF / WRONG BRANCH / WRONG REPO as the entrypoint pins them in production
new_box 10; stage gateway
( sandbox_env; REF_FMT='refs/tags/v%s'; main deploy $FXV ) >"$B/stdout" 2>"$B/stderr"; eq "production ref pin: a release not signed from refs/tags/vX.Y.Z refused" "$?" 1
grep -q "manifest ref is not refs/tags/v$FXV" "$B/stderr" && ok || bad "wrong ref reported"
( sandbox_env; BRANCH_RE='^release/'; main deploy $FXV ) >"$B/stdout" 2>"$B/stderr"; eq "branch pin: commit claimed on main refused when only release/* is allowed" "$?" 1
grep -q "not on main or release" "$B/stderr" && ok || bad "wrong branch reported"
( sandbox_env; REPO_GATEWAY=gun025bba/other; main deploy $FXV ) >"$B/stdout" 2>"$B/stderr"; eq "repo pin: other repo refused" "$?" 1
new_box 11; stage web gateway; run_main deploy $FXV; eq "web release staged as a gateway refused (kind)" "$?" 1
new_box 12; stage gateway web; run_main deploy-web $FXV; eq "gateway release staged as web refused (kind)" "$?" 1
new_box 13; stage web; ( sandbox_env; REPO_WEB=gun025bba/eve-serving; REPO_GATEWAY=gun025bba/eve-web; main deploy-web $FXV ) >/dev/null 2>&1; eq "web kind accepted only from the web repo pin" "$?" 0
new_box 14; stage gateway; ( sandbox_env; HOST_ARCH_WANT=not-this-arch; main deploy $FXV ) >/dev/null 2>&1; eq "wrong host architecture refused" "$?" 1
new_box 15; stage gateway; echo 9 >"$B/state/schema"; run_main deploy $FXV; eq "schema mismatch refused" "$?" 1
# production constants (what the real Mac enforces)
eq "prod: signer is the reusable workflow on main" "$SIGNER_IDENTITY" "https://github.com/gun025bba/eve-serving/.github/workflows/deploy-sign.yml@refs/heads/main"
eq "prod: issuer" "$OIDC_ISSUER" https://token.actions.githubusercontent.com
eq "prod: tag-push trigger" "$SIGNER_TRIGGER" push
eq "prod: ref is the tag" "$(printf "$REF_FMT" 5.0.2)" refs/tags/v5.0.2
eq "prod: gateway repo" "$REPO_GATEWAY" gun025bba/eve-serving
eq "prod: web repo" "$REPO_WEB" gun025bba/eve-web
for b in main release/5.0.2 release/10.0.0; do [[ "$b" =~ $BRANCH_RE ]] && ok || bad "prod: branch $b allowed"; done
for b in feat/x release/5.0 release/05.0.0 main2 xmain "release/5.0.2/x" refs/heads/main hotfix/1.2.3 ""; do [[ "$b" =~ $BRANCH_RE ]] && bad "prod: branch [$b] must be refused" || ok; done
eq "prod trusted root pin matches the committed file" "$(sha256 "$D/trusted_root.json")" "$TRUSTED_ROOT_SHA256"
case " $COSIGN_SHA256S " in *" 9f9b8cd557cf2e5b3df3373a00baa005a86b02391e3e06dd0ce37b3a1533d3a4 "*) ok;; *) bad "prod pins cosign darwin-arm64";; esac

# 5. WRONG SHA: artifact differs from the (validly signed) manifest
new_box 16; stage gateway; mkdir "$B/t" && ( cd "$B/t" && tar -xf "$FX/eve-gateway-$FXV.tar" && echo evil >gateway && tar -cf "$B/staging/eve-gateway-$FXV.tar" eve-gw gateway )
run_main deploy $FXV; eq "tampered tar (valid manifest + signature) refused" "$?" 1
grep -q "artifact hash != manifest" "$B/stderr" && ok || bad "tampered tar fails on the bundle sha256"
eq "wrong sha: live untouched" "$(cat "$B/bin/gateway")" gw-old
new_box 17; stage gateway; printf 'x' >>"$B/staging/eve-gateway-$FXV.tar"; run_main deploy $FXV; eq "one appended byte refused" "$?" 1
new_box 18; stage web; printf 'x' >>"$B/staging/eve-web-$FXV.tar"; run_main deploy-web $FXV; eq "web: one appended byte refused" "$?" 1
eq "web wrong sha: live untouched" "$(cat "$B/web/index.html")" old
# inner hash check: a tar whose own hash matches the manifest but whose member does not cannot exist without re-signing; check the member check by function
new_box 19; stage gateway; ( sandbox_env; WORK=$B/w; mkdir -p $WORK/x; cp "$FX/eve-gateway-$FXV.MANIFEST" $WORK/MANIFEST; tar -xf "$FX/eve-gateway-$FXV.tar" -C $WORK/x
  [ "$(manifest_get $WORK/MANIFEST sha256.gateway)" = "$(sha_of $WORK/x/gateway)" ] && [ "$(manifest_get $WORK/MANIFEST sha256.eve-gw)" = "$(sha_of $WORK/x/eve-gw)" ] ); eq "manifest member hashes match the fixture's members" "$?" 0

# 6. staging hygiene
new_box 20; stage gateway; rm "$B/staging/eve-gateway-$FXV.tar"; ln -s "$FX/eve-gateway-$FXV.tar" "$B/staging/eve-gateway-$FXV.tar"
run_main deploy $FXV; eq "symlinked staging file refused" "$?" 1
new_box 21; stage gateway; rm "$B/staging/eve-gateway-$FXV.MANIFEST"; run_main deploy $FXV; eq "missing manifest refused" "$?" 1
new_box 22; stage gateway; head -c 5000 /dev/zero | tr '\0' 'a' >"$B/staging/eve-gateway-$FXV.MANIFEST"; run_main deploy $FXV; eq "oversized manifest refused" "$?" 1
for evil in "$(cat "$FX/eve-gateway-$FXV.MANIFEST")"$'\nextra=1' "$(cat "$FX/eve-gateway-$FXV.MANIFEST")"$'\nversion=9.9.9' "$(cat "$FX/eve-gateway-$FXV.MANIFEST")"$'\n$(id)=x'; do
